-- =====================================================================
-- V20261028_012__fix_identity_generated_by_default.sql
-- 起因：V20261028_010 把主键建成 `GENERATED ALWAYS AS IDENTITY`，
--       而实体主键用 MyBatis-Plus 的 IdType.ASSIGN_ID / AUTO 会显式传 id，
--       PG 报「cannot insert a non-DEFAULT value into column "id"（列是 GENERATED ALWAYS）」→ 插入 500。
-- 修法：改为 `GENERATED BY DEFAULT AS IDENTITY` —— 显式给值就用，不给就自增（两种写法都兼容）。
-- =====================================================================

ALTER TABLE over_age_worker ALTER COLUMN id SET GENERATED BY DEFAULT;
ALTER TABLE scan_record ALTER COLUMN id SET GENERATED BY DEFAULT;
ALTER TABLE takeout_locker ALTER COLUMN id SET GENERATED BY DEFAULT;
ALTER TABLE locker_slot ALTER COLUMN id SET GENERATED BY DEFAULT;
ALTER TABLE supplier_evaluations ALTER COLUMN evaluation_id SET GENERATED BY DEFAULT;
